  childs_thing: kit('childs_thing', beam('Jet du lance-flammes de Childs', 1.2), guard('Tenir l’accès du groupe dans le bunker'), defend('Repli de Childs derrière une cloison'), 'Childs emploie le lance-flammes et tente de sécuriser la station ; il ne reçoit pas les propriétés de l’imitation.'),
  blair_thing: kit('blair_thing', buff('Blair examine les tissus'), buff('Simulation du risque d’assimilation'), defend('Isolement du scientifique au laboratoire'), 'Le Blair humain du début de The Thing étudie la biologie et l’expansion du risque ; la table n’utilise pas sa version imitée.'),
  tintin_hero: kit('tintin_hero', hit('Direct du reporter Tintin'), buff('Relier les indices de l’enquête'), defend('Esquive du jeune reporter'), 'Tintin pratique le corps-à-corps et mène des enquêtes ; l’action secondaire demeure une déduction de reporter.'),
  captain_haddock: kit('captain_haddock', buff('Haddock avertit les compagnons'), guard('Ordre de sauvetage en mer'), defend('Appui derrière le bastingage'), 'Haddock est capitaine et aide ses compagnons ; ses avertissements n’infligent pas de dégâts sonores et aucun alcool ne donne un bonus.'),
  professor_calculus: kit('professor_calculus', buff('Tournesol consulte son pendule'), buff('Comparer les mesures scientifiques'), defend('Rester derrière le poste d’expérience'), 'Tournesol emploie observation, pendule et science ; il ne reçoit pas automatiquement l’arme ultrasonique d’une intrigue comme attaque personnelle.'),
  tommy_heavenly_avatar: kit('tommy_heavenly_avatar', buff('Pray — première phrase de Tommy'), buff('Pray — reprise rock du refrain'), defend('Pause de Tommy au retour de scène'), 'L’avatar Tommy Heavenly6 représente la voix rock de Pray ; aucun pouvoir surnaturel n’est attribué à Tomoko Kawase.'),
  goth_candy_echo: kit('goth_candy_echo', buff('Lollipop Candy — cue de la transition'), buff('Relais du tableau Halloween'), defend('Sortie sûre du décor Goth Candy'), 'Goth Candy Echo est un rôle musical local inspiré de Lollipop Candy BAD girl ; le tableau n’est pas une malédiction offensive.'),
  punk_bunny_guard: kit('punk_bunny_guard', buff('Vérifier le passage près des accessoires'), guard('Dégager le décor de la scène Halloween'), defend('Se tenir derrière le cadre de scène'), 'Punk Bunny Guard est un rôle local de régie costumée ; sa fonction consiste à protéger le passage sans technique canonique personnelle inventée.'),
  val_tremors: kit('val_tremors', buff('Val observe le prochain rocher'), guard('Guider le saut hors du sol meuble'), defend('Appui de Val sur la roche'), 'Val organise les déplacements entre roches et toits dans Tremors ; les gestes aident à éviter la détection des Graboids.'),
  earl_tremors: kit('earl_tremors', buff('Earl repère une vibration suspecte'), buff('Annoncer le moment de traverser'), defend('Immobilité sur le point rocheux d’Earl'), 'Earl comprend les réactions des Graboids aux vibrations ; ses gestes donnent une information et un appui sûr, sans pouvoir sismique.'),
  burt_tremors: kit('burt_tremors', shot('Tir du fusil de Burt'), shot('Appui lourd du sous-sol', 1.8), defend('Couvert derrière la réserve du sous-sol'), 'Burt Gummer dispose d’armes à feu dans son sous-sol ; les actions restent des tirs fictifs et un couvert sans instructions de fabrication.'),
  kirie_uzumaki: kit('kirie_uzumaki', buff('Kirie remarque l’anomalie du quartier'), guard('Rester avec Shuichi sur le trajet'), defend('Retrait avant la zone de spirale'), 'Kirie observe la malédiction et tente de s’échapper ; elle n’en contrôle pas les spirales.'),
  shuichi_uzumaki: kit('shuichi_uzumaki', buff('Shuichi partage son inquiétude'), guard('Préparer la sortie de Kurouzu'), defend('Se tenir hors du rassemblement de la spirale'), 'Shuichi reconnaît le danger et demande à Kirie de quitter la ville ; la table fournit des avertissements plutôt qu’une manipulation du phénomène.'),
  azami_uzumaki: kit('azami_uzumaki', buff('Observer la marque d’Azami'), area('Attraction de l’écho spiralé', 1.6), defend('Recul de la silhouette d’Azami'), 'The Scar établit l’attraction surnaturelle de la marque ; l’impact de l’écho est abstrait et non graphique, sans ajout d’arme corporelle.'),
  chihiro_ogino: kit('chihiro_ogino', buff('Chihiro se souvient du vrai nom'), cleanse('Partager le gâteau du dieu de la rivière'), defend('S’abriter dans les bains'), 'Chihiro s’appuie sur mémoire, entraide et gâteau médicinal reçu du dieu ; elle ne lance pas de nouveau sort offensif.'),
  haku_spirited: kit('haku_spirited', buff('Haku indique le chemin des bains'), guard('Porter un compagnon en forme de dragon'), defend('Repli du dragon blanc'), 'Haku peut prendre forme de dragon et guider Chihiro ; le transport protège sans lui inventer de souffle élémentaire.'),
  lin_spirited: kit('lin_spirited', buff('Lin explique le travail aux bains'), guard('Montrer la sortie de service à Chihiro'), defend('Abri derrière le poste de travail'), 'Lin enseigne les tâches et les passages des bains à Chihiro ; ses actions restent de l’aide pratique.'),
  tea_ygo: kit('tea_ygo', buff('Téa appelle ses amis à tenir bon'), buff('Rappel du lien du groupe de Yugi'), defend('Se placer derrière la zone de duel'), 'Téa fournit du courage et maintient l’amitié du groupe dans Duel Monsters ; elle ne reçoit pas une attaque d’un monstre de carte.'),
  bakura_ygo: kit('bakura_ygo', buff('Ryo explique une règle du jeu de plateau'), buff('Préparer un plan avec les compagnons'), defend('Retrait du joueur Ryo'), 'Cette identité est Ryo Bakura et sa pratique des jeux de plateau ; elle ne reprend pas la violence ou les pouvoirs de Yami Bakura.'),
  mai_ygo: kit('mai_ygo', shot('Harpie Lady — attaque de carte'), area('Harpie Lady Sisters — combinaison de cartes', 1.8), defend('Placement prudent de la duelliste Mai'), 'Mai utilise les Harpie Lady de son deck ; les dégâts sont des actions de monstres de cartes adaptés et non des griffes personnelles de la duelliste.'),
  zeke_zamn: kit('zeke_zamn', shot('Jet du pistolet à eau de Zeke'), buff('Zeke repère un voisin à sauver'), defend('Repli derrière la clôture de Zeke'), 'Zeke commence avec le pistolet à eau et sauve les voisins dans Zombies Ate My Neighbors ; l’observation est un soutien de mission.'),
  julie_zamn: kit('julie_zamn', shot('Pistolet à eau de Julie'), shot('Lancer de canette de soda', 1.7), defend('Se couvrir derrière le décor de Julie'), 'Julie peut utiliser le pistolet à eau et les canettes de soda de l’arsenal partagé ; la table garde ces objets de jeu cartoon.'),
  neighbor_rescue: kit('neighbor_rescue', buff('Signaler le voisin en sécurité'), guard('Ouvrir le trajet de sauvetage suivant'), defend('Rester à l’abri après le secours'), 'Neighbor Rescue représente l’objectif de sauver les civils du jeu ; le voisin secouru ne reçoit pas une attaque de monstre.')
